const props = Object.assign({}, v.properties || {});
// aliases are in order of preference: the first one that holds a value wins
const find = (field) => {
  const keys = Object.keys(props);
  const hit = (a) => keys.filter(k => k.trim() === a || k.trim().toLowerCase() === a);
  for (const a of ALIASES[field]) {
    const k = hit(a).find(x => String(props[x] == null ? "" : props[x]).trim() !== "");
    if (k !== undefined) return k;
  }
  for (const a of ALIASES[field]) { const k = hit(a)[0]; if (k !== undefined) return k; }   // present but empty
  return undefined;
};
